@Composable fun AttendanceAlertsScreen(api:ApiClient,workspace:String,onExpired:()->Unit){
    var query by rememberSaveable{mutableStateOf("")};var page by rememberSaveable(query){mutableIntStateOf(1)};var status by rememberSaveable{mutableStateOf("pending")};var filters by remember{mutableStateOf(JSONObject())};var refine by remember{mutableStateOf(false)};var revision by remember{mutableIntStateOf(0)}
    var selected by remember{mutableStateOf(setOf<String>())};var review by remember{mutableStateOf<JSONObject?>(null)};var jobs by remember{mutableStateOf<JSONObject?>(null)};var busy by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};var breakdown by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope()
    fun preview(items:JSONArray){scope.launch{busy=true;error=null;try{review=api.post("workspace/alerts.php",JSONObject().put("action","preview").put("items",items))}catch(c:CancellationException){throw c}catch(f:Exception){if(f is ApiException&&f.status==401)onExpired()else error=f.message}finally{busy=false}}}
    RemotePanel(api,"workspace/alerts.php?workspace=$workspace&q=${encoded(query)}&alert=$status&page=$page&revision=$revision&"+filters.keys().asSequence().joinToString("&"){"${encoded(it)}=${encoded(filters.text(it))}"},onExpired){json->
        val rows=(json.optJSONArray("items")?:JSONArray()).objects()
        LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(14.dp)){
            item{PageTitle("Attendance summary & alerts","Finalized subject totals include lecture and laboratory sessions.")}
            item{OutlinedTextField(query,{query=it},label={Text("Search student, ID or subject")},singleLine=true,modifier=Modifier.fillMaxWidth());SearchSelect("Show",status,listOf("pending" to "Pending notices","all" to "All subject totals","threshold" to "Threshold reached","dropped" to "Dropped subjects","review" to "Mixed enrollment — review")){status=it;page=1;selected=emptySet()};TextButton(onClick={refine=true}){Text("Refine view (${filters.length()})")}}
            error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}
            if(json.optBoolean("can_send"))item{Button(onClick={preview(JSONArray(selected.map{key->JSONObject().put("student_id",key.substringBefore(':').toLong()).put("offering_id",key.substringAfter(':').toLong())}))},enabled=selected.isNotEmpty()&&!busy&&json.optBoolean("ready")){Text("Review selected messages (${selected.size})")};if(!json.optBoolean("ready"))Text("SMS is disabled or awaiting administrator configuration.",style=MaterialTheme.typography.bodySmall)}
            if(rows.isEmpty())item{EmptyState("No matching alerts","Try another filter. A threshold notice never automatically drops a student.")}
            items(rows){row->val key="${row.text("student_id")}:${row.text("offering_id")}";Panel{
                Row(Modifier.fillMaxWidth()){Column(Modifier.weight(1f)){Text(row.text("student_name"),style=MaterialTheme.typography.titleMedium);Text(row.text("school_id"),style=MaterialTheme.typography.bodySmall)};if(json.optBoolean("can_send"))Checkbox(key in selected,{checked->selected=if(checked&&selected.size<100)selected+key else selected-key},enabled=row.optBoolean("can_review")&&json.optBoolean("ready"))}
                Text("${row.text("course_code")} · ${row.text("course_title")}");Text("${row.text("section_name")} · ${row.text("semester_name")} · ${row.text("school_year_name")}",style=MaterialTheme.typography.bodySmall)
                Text("Absences ${row.text("absences")} · Tardies ${row.text("tardies")} · Converted ${row.text("converted")}",style=MaterialTheme.typography.bodyMedium);Text("Total absence equivalents: ${row.text("total_equivalents")}",style=MaterialTheme.typography.titleSmall)
                if(row.optInt("mixed_enrollment")>0){StatusPill("Enrollment needs review");Text("Lecture and laboratory enrollment states disagree. An academic manager must review them before messaging.",style=MaterialTheme.typography.bodySmall)};if(row.text("kind")=="threshold")StatusPill("Attendance threshold reached")else if(row.text("kind")=="dropped")StatusPill("Dropped subject")
                if(row.text("sms_status").isNotBlank())Text("SMS: ${row.text("sms_status")}",style=MaterialTheme.typography.bodySmall)
                TextButton(onClick={breakdown=row.text("calculation")}){Text("How calculated")}
                if(json.optBoolean("can_send")){Button(onClick={preview(JSONArray().put(JSONObject().put("student_id",row.optLong("student_id")).put("offering_id",row.optLong("offering_id"))))},enabled=row.optBoolean("can_review")&&json.optBoolean("ready")&&!busy){Text("Review SMS")};if(!row.optBoolean("can_review"))Text(if(row.text("phone_number").isBlank())"No mobile number saved. Ask an account manager to update it."else"This notice is not eligible for another send.",style=MaterialTheme.typography.bodySmall)}
            }}
            item{val pagination=json.optJSONObject("pagination")?:JSONObject();PageControls(page,pagination.optInt("pages",1),pagination.optInt("total")){page=it}}
        }
    }
    if(refine)AttendanceAlertFilters(api,workspace,filters,onExpired,{refine=false}){filters=it;page=1;selected=emptySet()}
    breakdown?.let{AlertDialog(onDismissRequest={breakdown=null},title={Text("Absence equivalents")},text={Text(it)},confirmButton={TextButton(onClick={breakdown=null}){Text("Close")}})}
    review?.let{data->AlertDialog(onDismissRequest={if(!busy)review=null},title={Text("Review attendance messages")},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(14.dp)){items((data.optJSONArray("items")?:JSONArray()).objects()){item->Text(item.text("student_name"),style=MaterialTheme.typography.titleMedium);if(item.optBoolean("blocked"))Text(item.text("reason"),color=MaterialTheme.colorScheme.error)else{Text("${item.text("recipient")} · ${item.text("course_code")}\n${item.text("section_name")} · ${item.text("semester_name")}");Text(item.text("calculation"));Text(item.text("message"));Text("Estimated segments: ${item.optJSONObject("segments")?.optInt("segments")?:0} · ${item.optJSONObject("segments")?.text("type")}",style=MaterialTheme.typography.bodySmall)};HorizontalDivider()};error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}}},dismissButton={TextButton(onClick={review=null},enabled=!busy){Text("Cancel")}},confirmButton={Button(enabled=!busy&&(data.optJSONArray("items")?:JSONArray()).objects().any{!it.optBoolean("blocked")},onClick={scope.launch{busy=true;try{jobs=api.post("workspace/alerts.php",JSONObject().put("action","enqueue").put("review_token",data.text("review_token")));review=null;selected=emptySet();revision++}catch(c:CancellationException){throw c}catch(f:Exception){if(f is ApiException&&f.status==401)onExpired()else error=f.message}finally{busy=false}}}){Text(if(busy)"Queueing…"else"Confirm & send")}})}
    jobs?.let{SmsProgress(api,it,onExpired){jobs=null;revision++}}
}

@Composable private fun SmsProgress(api:ApiClient,jobs:JSONObject,onExpired:()->Unit,close:()->Unit){var result by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf<String?>(null)};val ids=jobs.optJSONArray("message_ids")?:JSONArray();val path="workspace/alerts.php?mode=progress&ids="+(0 until ids.length()).joinToString(","){ids.getLong(it).toString()};val lifecycle=androidx.lifecycle.compose.LocalLifecycleOwner.current;LaunchedEffect(path,lifecycle){lifecycle.lifecycle.repeatOnLifecycle(androidx.lifecycle.Lifecycle.State.STARTED){while(true){try{result=api.get(path);if((result?.optJSONArray("items")?:JSONArray()).objects().none{it.text("status") in listOf("queued","sending","accepted")})break}catch(c:CancellationException){throw c}catch(f:Exception){if(f is ApiException&&f.status==401){onExpired();break};error=f.message;break};delay(3000)}}};AlertDialog(onDismissRequest=close,title={Text("Message delivery")},text={LazyColumn{item{Text("Provider acceptance and confirmed delivery are tracked separately. Delivery unknown needs review before another send.")};items((result?.optJSONArray("items")?:JSONArray()).objects()){row->Text(row.text("student_name").ifBlank{"Recipient"},style=MaterialTheme.typography.titleSmall);Text("${row.text("school_id")} \u00b7 ${row.text("course_code")} \u00b7 ${row.text("section_name")}",style=MaterialTheme.typography.bodySmall);StatusPill(row.text("status_label").ifBlank{row.text("status")});if(row.text("error_message").isNotBlank())Text(row.text("error_message"),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.error);HorizontalDivider()};error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}}},confirmButton={TextButton(onClick=close){Text("Close")}})}

@Composable fun SmsSettingsScreen(api:ApiClient,onExpired:()->Unit){var revision by remember{mutableIntStateOf(0)};var edit by remember{mutableStateOf(false)};var result by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();RemotePanel(api,"workspace/sms-settings.php?revision=$revision",onExpired){json->val settings=json.optJSONObject("settings")?:JSONObject();LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(14.dp)){item{PageTitle("SMS settings","Administrator-managed PhilSMS configuration. Saved tokens are never returned.")};item{Panel{StatusPill(if(settings.optInt("enabled")==1||settings.optBoolean("enabled"))"Enabled"else"Disabled");Text("Sender: PhilSMS (fixed for this account)");Text("Absence threshold: ${settings.text("absence_threshold")}");Button(onClick={edit=true}){Text("Configure SMS")};OutlinedButton(onClick={scope.launch{try{val response=api.post("workspace/sms-settings.php",JSONObject().put("action","balance")).optJSONObject("result")?:JSONObject();result=if(response.optBoolean("ok"))"Connected. Balance: ${response.optJSONObject("data")?.text("balance")?.ifBlank{"Unavailable"}}"else"Connection failed: ${response.text("error")}"}catch(f:Exception){result=f.message}}}){Text("Test connection & balance")};result?.let{Text(it)}}}};if(edit)NativeEditor("Configure SMS",listOf(NativeField("enabled","Integration",settings.text("enabled"),listOf("0" to "Disabled","1" to "Enabled")),NativeField("api_token","Replace API token (leave blank to keep)",type="secret"),NativeField("absence_threshold","Absence threshold",settings.text("absence_threshold")),NativeField("threshold_template","Attendance template",settings.text("threshold_template"),type="multiline"),NativeField("dropped_template","Dropped-subject template",settings.text("dropped_template"),type="multiline")),onExpired,{edit=false}){input->api.post("workspace/sms-settings.php",input.put("action","save"));revision++}}}
